<?php
require_once '../includes/auth.php';require_once '../includes/functions.php';if(isTenantUser())requireTenant();global $conn;
$cols=[];$q=$conn->query("SHOW COLUMNS FROM ip_pools");while($x=$q->fetch_assoc())$cols[]=$x['Field'];$has=fn($c)=>in_array($c,$cols,true);$tid=getCurrentTenantId();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$map=['name'=>trim($_POST['name']??''),'pool_name'=>trim($_POST['name']??''),'network'=>trim($_POST['network']??''),'cidr'=>trim($_POST['cidr']??''),'gateway'=>trim($_POST['gateway']??''),'start_ip'=>trim($_POST['start_ip']??''),'end_ip'=>trim($_POST['end_ip']??''),'status'=>$_POST['status']??'active','description'=>trim($_POST['description']??'')];$f=[];$v=[];$t='';foreach($map as $c=>$x)if($has($c)&&!in_array($c,$f,true)){$f[]=$c;$v[]=$x;$t.='s';}if($has('tenant_id')){$f[]='tenant_id';$v[]=$tid;$t.='i';}$st=$conn->prepare("INSERT INTO ip_pools (".implode(',',$f).") VALUES (".implode(',',array_fill(0,count($f),'?')).")");if($st){$st->bind_param($t,...$v);if($st->execute())redirect('index.php');$errors[]=$st->error;}}
?>
